/* Recepten · receptkaart zonder foto: zes voorstellen voor de lege staat van het bord · 2 nov. */
(() => {
  const world = document.getElementById("world");
  const IMG = { aard: "data:image/webp;base64,", olie: "data:image/webp;base64,", zout: "data:image/webp;base64,", rozemarijn: "data:image/webp;base64,", spaghetti: "data:image/webp;base64," };
  const INK = "#101130";
  const SUB = "#8a8ea3";
  const BLUE = "#4f55f1";
  const DOT = "#5AC8FA";
  const FONT = "Inter,system-ui,sans-serif";
  const ingredients = [IMG.aard, IMG.olie, IMG.zout];

  /* Receptkaart: 160 breed, verloop bovenaan, bord 84 %, naam + aantal ingrediënten. */
  const card = (plate, { name = "Aardappelen in de airfryer", count = "3 ingrediënten", top = "#eef0fb", mid = "#f6f7fd" } = {}) =>
    `<div style="width:160px;flex:none;display:flex;flex-direction:column;gap:12px;border-radius:18px;background:#fff linear-gradient(180deg,${top} 0%,${mid} 55%,transparent 100%);padding:16px 10px 14px;text-align:center;box-shadow:inset 0 0 0 1px #e8e9ef,0 1px 2px rgba(16,17,48,.04)">
      <div style="position:relative;margin:0 auto;width:84%;aspect-ratio:1">${plate}</div>
      <div style="display:flex;flex-direction:column;align-items:center;gap:3px;min-height:58px"><b style="font:600 14px/19px ${FONT};color:${INK}">${name}</b><span style="margin-top:auto;display:flex;align-items:center;gap:6px;font:400 12px/16px ${FONT};color:${SUB}"><i style="width:7px;height:7px;border-radius:50%;background:${DOT}"></i>${count}</span></div>
    </div>`;
  const photoCard = () => card(`<img src="${IMG.spaghetti}" style="width:100%;height:100%;border-radius:50%;object-fit:cover;filter:drop-shadow(2px 3px 3px rgba(80,50,10,.22)) drop-shadow(8px 11px 10px rgba(110,70,20,.3))">`, { name: "Spaghetti bolognese", count: "10 ingrediënten", top: "#f8e2d2", mid: "#fbefe6" });
  const whitePlate = (inner = "", extra = "") => `<div style="position:absolute;inset:0;border-radius:50%;background:#fff;box-shadow:0 10px 22px -12px rgba(16,17,48,.35),inset 0 0 0 7px #f6f6f9,inset 0 0 0 8px #ececf2;${extra}">${inner}</div>`;
  const ing = (src, size, x, y, rot = 0) => `<img src="${src}" style="position:absolute;width:${size}%;left:${x}%;top:${y}%;transform:translate(-50%,-50%) rotate(${rot}deg);filter:drop-shadow(0 3px 4px rgba(16,17,48,.18))">`;
  const icon = {
    spark: (s = 18) => `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2.5l1.9 5.6 5.6 1.9-5.6 1.9L12 17.5l-1.9-5.6L4.5 10l5.6-1.9z"/><path d="M19 15l.9 2.1 2.1.9-2.1.9L19 21l-.9-2.1-2.1-.9 2.1-.9z" opacity=".7"/></svg>`,
    cam: (s = 14) => `<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 8h3l1.5-2h7L17 8h3v11H4z"/><circle cx="12" cy="13" r="3.5"/></svg>`,
  };

  /* 1 · Ingrediëntenbord: zoals de kalender, drie ingrediënten op een wit bord. */
  const one = (empty) => card(whitePlate(empty ? "" : ing(ingredients[0], 52, 50, 40) + ing(ingredients[1], 30, 30, 66, -10) + ing(ingredients[2], 28, 70, 66, 8)), empty ? { name: "Gemengde salade", count: "0 ingrediënten", top: "#e6f6fe", mid: "#f3fbff" } : { top: "#e6f6fe", mid: "#f3fbff" });
  /* 2 · Hoofdingrediënt groot op het bord. */
  const two = (empty) => card(whitePlate(empty ? "" : ing(ingredients[0], 74, 50, 50, -6)), empty ? { name: "Gemengde salade", count: "0 ingrediënten", top: "#f6efe2", mid: "#fbf7f0" } : { top: "#f6efe2", mid: "#fbf7f0" });
  /* 3 · Leeg bord met bestek, als lijntekening. */
  const cutlery = `<svg viewBox="0 0 120 120" style="position:absolute;inset:-14% -22%;width:144%;height:128%;overflow:visible" fill="none" stroke="#c9ccdb" stroke-width="2.2" stroke-linecap="round"><path d="M6 30v26M2 30v12a4 4 0 0 0 8 0V30M6 56v34"/><path d="M114 30c-5 4-6 14-6 24h6M114 30v60"/></svg>`;
  const three = (empty) => card(`${cutlery}<div style="position:absolute;inset:0;border-radius:50%;background:#fff;box-shadow:0 10px 22px -14px rgba(16,17,48,.3),inset 0 0 0 1.5px #e3e5ee"><div style="position:absolute;inset:18%;border-radius:50%;box-shadow:inset 0 0 0 1.5px #eceef4"></div></div>`, empty ? { name: "Gemengde salade", count: "0 ingrediënten", top: "#f1f2f6", mid: "#f8f8fb" } : { top: "#f1f2f6", mid: "#f8f8fb" });
  /* 4 · Monogram in de categoriekleur. */
  const four = (empty) => card(`<div style="position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ffffff 0%,#dff3fd 70%);box-shadow:inset 0 0 0 1.5px rgba(90,200,250,.35)"></div><span style="position:absolute;inset:0;display:grid;place-items:center;font:800 54px/1 ${FONT};letter-spacing:-.02em;color:#2a9fd6">${empty ? "G" : "A"}</span>`, empty ? { name: "Gemengde salade", count: "0 ingrediënten", top: "#e6f6fe", mid: "#f3fbff" } : { top: "#e6f6fe", mid: "#f3fbff" });
  /* 5 · Gestippeld bord met «Foto maken» (AI-foto laten maken). */
  const five = (empty) => card(`<div style="position:absolute;inset:0;border-radius:50%;background:rgba(255,255,255,.7);border:2px dashed #c3c6f5"></div><div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:${BLUE}">${icon.spark(24)}<span style="display:inline-flex;align-items:center;gap:5px;height:28px;padding:0 11px;border-radius:999px;background:#fff;box-shadow:0 4px 12px -6px rgba(79,85,241,.5);font:700 12px/1 ${FONT};color:${BLUE}">Foto maken</span></div>`, empty ? { name: "Gemengde salade", count: "0 ingrediënten" } : {});
  /* 6 · Waaier van ingrediënten op een zacht rond vlak. */
  const chip = (src, rot, dx, dy, z) => `<span style="position:absolute;left:50%;top:50%;width:56%;aspect-ratio:1;border-radius:16px;background:#fff;display:grid;place-items:center;box-shadow:0 8px 16px -10px rgba(16,17,48,.45),inset 0 0 0 1px #eceef4;transform:translate(calc(-50% + ${dx}%),calc(-50% + ${dy}%)) rotate(${rot}deg);z-index:${z}"><img src="${src}" style="width:76%"></span>`;
  const six = (empty) => card(`<div style="position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle,#ffffff 0%,#e9f6fd 75%)"></div>${empty ? `<span style="position:absolute;inset:0;display:grid;place-items:center;color:#9fd8f4">${icon.cam(30)}</span>` : chip(ingredients[1], -12, -34, 2, 1) + chip(ingredients[2], 10, 34, 4, 2) + chip(ingredients[0], -2, 0, 8, 3)}`, empty ? { name: "Gemengde salade", count: "0 ingrediënten", top: "#e6f6fe", mid: "#f3fbff" } : { top: "#e6f6fe", mid: "#f3fbff" });

  const V = [
    { key: "1", name: "Ingrediëntenbord", why: "Een wit bord met de eerste drie ingrediëntfoto's, zoals de borden op de kalender. Zonder ingrediënten blijft het een leeg wit bord. Het verloop krijgt de categoriekleur (bijgerecht = lichtblauw) in plaats van lavendel.", html: one },
    { key: "2", name: "Hoofdingrediënt", why: "Alleen het eerste ingrediënt, groot en licht gekanteld op een wit bord: rustiger dan drie losse foto's en meteen herkenbaar (aardappelen). Warm neutraal verloop.", html: two },
    { key: "3", name: "Gedekt bord", why: "Een leeg wit bord met vork en mes als dunne lijntekening. Zegt «hier komt een gerecht» zonder te doen alsof er een foto is. Werkt voor elk recept, ook zonder ingrediënten.", html: three },
    { key: "4", name: "Monogram", why: "De beginletter groot op een zacht bord in de categoriekleur. Simpel en altijd beschikbaar; elke categorie krijgt haar eigen tint, zodat een rij zonder foto's toch afwisselt.", html: four },
    { key: "5", name: "Foto maken", why: "Een gestippeld bord met een sterretje en de pil «Foto maken», die meteen «Foto laten maken» (AI) opent. De lege staat wordt een uitnodiging in plaats van een gat.", html: five },
    { key: "6", name: "Ingrediëntenwaaier", why: "Drie ingrediënten als witte kaartjes in een waaier (−12° / +10° / −2°), dezelfde taal als de lege staten elders in de app. Zonder ingrediënten een zacht camera-icoon.", html: six },
  ];
  const b = document.createElement("section");
  b.className = "board iter";
  b.style.cssText = "left:0;top:0;width:1760px";
  b.innerHTML = `<style>.rn-opts{display:grid;grid-template-columns:repeat(2,840px);gap:56px 40px}.rn-stage{background:#f4f5fa;border-radius:26px;padding:28px;display:flex;gap:14px;align-items:stretch}.rn-stage *{box-sizing:border-box}.rn-opt .ag-opthd p{max-width:760px}.rn-cap{font:600 12px/16px ${FONT};color:${SUB};margin:10px 0 0 4px}</style><header class="bhd"><span class="bnum">RN</span><div><h2>Recepten · kaart zonder foto <span class="tag">6 voorstellen · 2 nov</span></h2><p>Nu krijgt een recept zonder foto een lavendel cirkel met een grijs afbeeldingsicoon: dat leest als «afbeelding kapot». Zes voorstellen voor het bord, telkens naast een kaart mét foto, met «Aardappelen in de airfryer» (3 ingrediënten) en een recept zonder ingrediënten.</p><p class="uses">Bouwt op: RecipePlateCard, kalenderbord, EmptyStateFan, FoodImageGeneratorSlideIn</p></div></header>
    <div class="rn-opts" style="margin-top:28px">${V.map((v) => `<div class="rn-opt"><div class="ag-opthd"><span class="ag-key">${v.key}</span><div><h3>${v.name}</h3><p>${v.why}</p></div></div><div class="rn-stage">${photoCard()}${v.html(false)}${v.html(true)}</div><p class="rn-cap">met foto · zonder foto · zonder foto én zonder ingrediënten</p></div>`).join("")}</div>`;
  world.appendChild(b);
  const others = [...world.children].filter((el) => el !== b && el.tagName === "SECTION");
  const topY = Math.min(...others.map((el) => el.offsetTop));
  b.style.top = `${topY - 240 - b.offsetHeight}px`;
})();
